CREATE TABLE contents(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,excerpt TEXT NOT NULL DEFAULT "",content TEXT NOT NULL,status TEXT NOT NULL,posted_at TEXT NOT NULL,images TEXT NOT NULL DEFAULT "[]",version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE users(id INTEGER PRIMARY KEY,login TEXT UNIQUE,password TEXT,role TEXT);
CREATE TABLE settings(name TEXT PRIMARY KEY,value TEXT);
CREATE TABLE requests(id INTEGER PRIMARY KEY,kind TEXT,data TEXT,status TEXT,created_at TEXT);
CREATE TABLE stats(day TEXT PRIMARY KEY,data TEXT);
CREATE TABLE revisions(id INTEGER PRIMARY KEY,content_id INTEGER,snapshot TEXT,created_at TEXT);
CREATE TABLE limits(key TEXT PRIMARY KEY,attempts INTEGER,expires INTEGER);